package br.com.sussmartcare.prehospital.application; import br.com.sussmartcare.prehospital.domain.*; import br.com.sussmartcare.prehospital.infrastructure.*; import br.com.sussmartcare.prehospital.infrastructure.outbox.EventOutbox; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PreHospitalApplicationService{private final PreHospitalRepository repo;private final EventOutbox outbox;public PreHospitalApplicationService(PreHospitalRepository r,EventOutbox o){repo=r;outbox=o;}@Transactional public PreHospitalEncounter create(UUID patient,UUID visit,String ambulance,UUID destination,Instant eta){var e=repo.save(new PreHospitalEncounter(patient,visit,ambulance,destination,eta));outbox.append("pre-hospital-encounter-created",e.getId().toString(),new EncounterCreated(e.getId(),patient,visit,ambulance,destination,eta));return e;}public PreHospitalEncounter get(UUID id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Atendimento pré-hospitalar não encontrado"));}@Transactional public PreHospitalEncounter eta(UUID id,Instant eta){var e=get(id);e.updateEta(eta);return repo.save(e);}@Transactional public PreHospitalEncounter risk(UUID id,String risk){var e=get(id);e.updateRisk(risk);repo.save(e);if("HIGH".equals(risk)||"EMERGENCY".equals(risk))outbox.append("pre-arrival-alert-created",id.toString(),new PreArrivalAlert(id,e.getPatientId(),e.getVisitId(),e.getDestinationFacilityId(),risk,e.getEstimatedArrivalAt()));return e;}public record EncounterCreated(UUID encounterId,UUID patientId,UUID visitId,String ambulanceId,UUID facilityId,Instant eta){}public record PreArrivalAlert(UUID encounterId,UUID patientId,UUID visitId,UUID facilityId,String riskLevel,Instant eta){} }
